/**
 * Um universo cheio de surpresas — a receita que segura as galáxias.
 *
 * São três sliders que precisam somar cem, e cada um erra de um jeito diferente:
 * matéria escura de menos e a galáxia se despedaça girando; energia escura de
 * menos e o cosmo colapsa; de mais e ele se rasga. A leitura já diz isso, mas
 * ler "as galáxias se despedaçam" não é ver.
 *
 * A cena é uma galáxia que reage à receita: ela se abre, se enrola ou fica no
 * lugar. E a coluna ao lado mostra as três frações contra os alvos — porque o
 * assunto do módulo é a PROPORÇÃO, não os números soltos.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  disco,
  type EstadoDaViz,
  infoDe,
  limitar,
  numeroDe,
  paleta,
  retangulo,
  rodape,
  texto,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

const ESTRELAS = 220;

/** Pseudoaleatório estável: a mesma estrela no mesmo braço a cada quadro. */
function semente(i: number, deslocamento = 0): number {
  const v = Math.sin((i + 1) * 91.7 + deslocamento * 31.4159) * 43758.5453;
  return v - Math.floor(v);
}

const universoEscuro: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;

    const comum = limitar(numeroDe(valores, 'comum', 0), 0, 100);
    const escura = limitar(numeroDe(valores, 'escura', 0), 0, 100);
    const energia = limitar(numeroDe(valores, 'energia', 0), 0, 100);
    const ok = info.ok === true;
    const miudo = limitar(A * 0.03, 8, 11);

    const alvos = (info.alvos ?? {}) as Readonly<Record<string, unknown>>;
    const alvoComum = numeroDe(alvos, 'comum', 4);
    const alvoEscura = numeroDe(alvos, 'escura', 22);
    const alvoEnergia = numeroDe(alvos, 'energia', 74);

    titulo(ctx, L, A, 'Tudo o que se vê é 4% — o resto segura o cosmo');

    // ── A galáxia ─────────────────────────────────────────────────────────
    const cx = L * 0.34;
    const cy = A * 0.48;
    const R = Math.min(L * 0.26, A * 0.28);

    // Matéria escura de menos: as estrelas se soltam. De mais: a espiral aperta.
    const coesao = limitar(escura / Math.max(1, alvoEscura), 0, 2.4);
    // Energia escura: sobra empurra tudo para fora, falta puxa para dentro.
    const expansao = (energia - alvoEnergia) / 100;

    const solta = limitar(1.6 - coesao, 0, 1.6);
    const raioMedio = R * (0.55 + solta * 0.5 + Math.max(0, expansao) * 1.4);
    const aperto = limitar(coesao, 0.2, 2.4);

    ctx.fillStyle = 'rgb(35 42 85 / 6%)';
    ctx.beginPath();
    ctx.arc(cx, cy, R * 1.15, 0, Math.PI * 2);
    ctx.fill();

    for (let i = 0; i < ESTRELAS; i++) {
      const braco = i % 2;
      const u = semente(i);
      // Espiral logarítmica: o aperto é o que a matéria escura decide.
      const raio = raioMedio * (0.12 + u * 0.95);
      const ang =
        braco * Math.PI + Math.log(1 + raio / (R * 0.2)) * (2.2 * aperto) + t * (0.35 / aperto);

      const desvio = (semente(i, 1) - 0.5) * R * 0.16 * (1 + solta);
      const x = cx + Math.cos(ang) * raio + desvio;
      const y = cy + Math.sin(ang) * raio * 0.62 + desvio * 0.5;

      const brilho = 0.35 + semente(i, 2) * 0.65;
      ctx.globalAlpha = brilho;
      disco(ctx, x, y, 1 + semente(i, 3) * 1.6, i % 7 === 0 ? cor.ouro : cor.azul);
    }
    ctx.globalAlpha = 1;

    // O bojo central, sempre lá.
    const halo = ctx.createRadialGradient(cx, cy, 0, cx, cy, R * 0.3);
    halo.addColorStop(0, 'rgb(255 236 180 / 95%)');
    halo.addColorStop(1, 'rgb(255 236 180 / 0%)');
    ctx.fillStyle = halo;
    ctx.beginPath();
    ctx.arc(cx, cy, R * 0.3, 0, Math.PI * 2);
    ctx.fill();

    const diagnostico = ok
      ? 'galáxia estável'
      : escura < alvoEscura - 3
        ? 'sem a "cola" invisível: as estrelas se soltam'
        : escura > alvoEscura + 3
          ? 'matéria escura demais: a espiral se enrola'
          : energia < alvoEnergia - 3
            ? 'sem energia escura: o cosmo colapsa'
            : energia > alvoEnergia + 3
              ? 'energia escura demais: a expansão rasga tudo'
              : 'quase lá';

    texto(ctx, diagnostico, cx, cy + R * 1.22, miudo * 0.95, {
      cor: ok ? cor.verde : cor.fraco,
      peso: 700,
    });

    // ── As três frações, contra os alvos ──────────────────────────────────
    const bx0 = L * 0.66;
    const bx1 = L * 0.96;
    const soma = comum + escura + energia;

    const faixa = (
      indice: number,
      rotulo: string,
      valor: number,
      alvo: number,
      tinta: string,
    ): void => {
      const y = A * 0.24 + indice * A * 0.17;
      const altura = limitar(A * 0.038, 7, 12);

      texto(ctx, rotulo, bx0, y - miudo * 0.9, miudo * 0.85, {
        cor: cor.fraco,
        peso: 600,
        alinhamento: 'left',
      });

      retangulo(ctx, bx0, y, bx1 - bx0, altura, altura / 2, cor.palha, cor.trilho, 1);
      retangulo(
        ctx,
        bx0,
        y,
        ((bx1 - bx0) * valor) / 100,
        altura,
        altura / 2,
        Math.abs(valor - alvo) <= 1.5 ? cor.verde : tinta,
      );

      // O alvo, um traço fixo: é a régua contra a qual o slider anda.
      const xAlvo = bx0 + ((bx1 - bx0) * alvo) / 100;
      ctx.strokeStyle = cor.texto;
      ctx.lineWidth = 1.6;
      ctx.beginPath();
      ctx.moveTo(xAlvo, y - 3);
      ctx.lineTo(xAlvo, y + altura + 3);
      ctx.stroke();

      texto(ctx, `${Math.round(valor)}%`, bx1, y + altura + miudo * 1.1, miudo * 0.85, {
        cor: cor.fraco,
        peso: 700,
        alinhamento: 'right',
      });
    };

    faixa(0, 'matéria comum', comum, alvoComum, cor.azul);
    faixa(1, 'matéria escura', escura, alvoEscura, cor.fraco);
    faixa(2, 'energia escura', energia, alvoEnergia, cor.ouro);

    texto(ctx, `soma ${Math.round(soma)}%`, (bx0 + bx1) / 2, A * 0.79, miudo * 1.05, {
      cor: Math.abs(soma - 100) <= 3 ? cor.verde : cor.erro,
      peso: 800,
    });

    rodape(
      ctx,
      L,
      A,
      ok,
      `${Math.round(alvoComum)}% comum · ${Math.round(alvoEscura)}% escura · ${Math.round(alvoEnergia)}% energia ✔`,
      Math.abs(soma - 100) > 3 ? 'O universo inteiro tem de dar 100%.' : 'Ajuste as três frações.',
      Math.abs(soma - 100) > 3 ? cor.erro : cor.fraco,
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A, t }) => desenhar(ctx, L, A, t),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default universoEscuro;
